// pseudo-code, include from SDK snippets
const { RedwoodClient } = require('redwood-sdk')
const Bottleneck = require('bottleneck')

const limiter = new Bottleneck({ reservoir: 50, reservoirRefreshAmount: 10, reservoirRefreshInterval: 1000 }) // burst 50, refill 10/s
const client = new RedwoodClient({ apiKey: process.env.REDWOOD_API_KEY, region: 'us-west-2' })

async function safeGenerate(payload) {
  return limiter.schedule(async () => {
    let attempt = 0
    const maxAttempts = 5
    while (attempt < maxAttempts) {
      try {
        const resp = await client.generate(payload, { timeout: 10000, headers: { 'X-Redwood-Trace': payload.traceId } })
        return resp
      } catch (err) {
        attempt++
        if (err.status === 429) {
          // reduce concurrency window on 429
          limiter.updateSettings({ reservoir: Math.max(1, Math.floor(limiter.settings.reservoir * 0.75)) })
        }
        if (attempt >= maxAttempts) throw err
        const backoff = Math.min(8000, 200 * Math.pow(2, attempt))
        await new Promise(r => setTimeout(r, Math.floor(Math.random() * backoff))) // full jitter
      }
    }
  })
}

